<script setup>
import {ref,computed,onBeforeUnmount,onMounted,nextTick} from 'vue';
import {Button,Tabs,Tab,Field,Switch,Popup,Picker,Collapse,CollapseItem,Progress,Cell,CellGroup} from 'vant';
import 'vant/es/button/style';import 'vant/es/tabs/style';import 'vant/es/tab/style';import 'vant/es/field/style';import 'vant/es/switch/style';import 'vant/es/popup/style';import 'vant/es/picker/style';import 'vant/es/collapse/style';import 'vant/es/collapse-item/style';import 'vant/es/progress/style';import 'vant/es/cell/style';import 'vant/es/cell-group/style';
const props=defineProps({controller:{type:Object,required:true}}),m=ref(props.controller.model),a=props.controller.actions,error=ref(''),picker=ref(false),opened=ref([]),input=ref(),composing=ref(false);
const stop=props.controller.subscribe(value=>{m.value=value;});onBeforeUnmount(stop);
function run(name,...args){try{error.value='';a[name](...args);}catch(e){error.value=e.message;}}
const unitHref=computed(()=>m.value.practice?.unit?'english-sentence-demo.html?unit='+m.value.practice.unit.id:'units.html?subject=english&term=upper');
const columns=computed(()=>m.value.entries?.filter(w=>w.id!==m.value.word.id).map(w=>({text:w.word+' · '+w.zh,value:w.id}))||[]);
function focus(){nextTick(()=>input.value?.focus());}
function start(){run('start');focus();}
function next(){run('next');focus();}
const touchTyping=window.matchMedia('(pointer: coarse)').matches;
function update(value){if(m.value.done){if(!composing.value&&/^[ \r\n]+$/.test(value.startsWith(m.value.draft)?value.slice(m.value.draft.length):''))next();else nextTick(()=>{const el=input.value?.$el.querySelector('textarea');if(el)el.value=m.value.draft;});return;}run('input',value,{composing:composing.value});}
function key(event){if(event.isComposing||composing.value||event.keyCode===229)return;if(event.repeat&&(event.key==='Enter'||event.key===' ')){event.preventDefault();return;}if(event.key==='Enter'||event.key===' '&&(m.value.done||m.value.phase==='word'||m.value.typing==='correct')){event.preventDefault();if(m.value.done)next();else run('submit');}}
function beforeInput(event){if(m.value.done&&!composing.value&&!event.isComposing&&event.cancelable&&(event.inputType==='insertLineBreak'||event.inputType==='insertParagraph'||/^[ \r\n]+$/.test(event.data||''))){event.preventDefault();next();}}
function previewKey(event){if(m.value.kind==='sentence'&&m.value.phase==='preview'&&!m.value.results&&!event.isComposing&&!event.ctrlKey&&!event.metaKey&&!event.altKey&&!event.repeat&&(event.key.length===1||event.key==='Enter')&&!event.target.closest('a,input,textarea,button')){event.preventDefault();start();}}
onMounted(()=>document.addEventListener('keydown',previewKey));onBeforeUnmount(()=>document.removeEventListener('keydown',previewKey));

</script>
<template>
<main class="english-labs" :data-kind="m.kind">
 <p v-if="error" role="alert">{{error}}</p><p v-if="m.notice" role="status">{{m.notice}} <Button v-if="m.pending" size="small" @click="run('save')">重试保存</Button></p>
 <template v-if="m.kind!=='sentence'">
  <header class="topbar"><Button tag="a" :href="m.backHref">← {{m.kind==='quiz'?'返回学习':'英语目录'}}</Button><span class="brand"><img class="brand-logo" :src="'brand-logo.webp'" alt="" width="32" height="32">逆流</span><Button v-if="m.kind==='visual'" @click="run('help',true)">使用说明</Button></header>
  <div class="shell">
   <header class="intro"><div><p class="eyebrow">{{m.kind==='quiz'?'LOOK & CHOOSE / 自己试一试':'ENGLISH IN MOTION / 看动作，记意思'}}</p><h1>{{m.kind==='quiz'?'看动作，选表达':'让单词动起来'}}<span>{{m.kind==='quiz'?'观察循环动画，选出对应的英文。':'把位置和动作，变成看得见的记忆。'}}</span></h1></div><span v-if="m.kind==='visual'" class="lesson-count">33<span>个词与短语</span></span></header>
   <nav class="topics"><Button :aria-pressed="m.group==='space'" @click="run('group','space')"><span class="topic-number">01</span><span>空间关系</span><small>17 个表达</small></Button><Button :aria-pressed="m.group==='motion'" @click="run('group','motion')"><span class="topic-number">02</span><span>行走与奔跑</span><small>16 个表达</small></Button></nav>
   <div class="visual-layout layout" :class="{'is-quiz':m.kind==='quiz'}">
    <aside v-if="m.kind==='visual'" class="vocabulary"><div class="list-title"><h2>{{m.group==='space'?'空间关系':'行走与奔跑'}}</h2><span>点选一个词</span></div><nav id="word-list"><Button v-for="word in m.entries" :key="word.id" :aria-current="m.word.id===word.id?'true':undefined" @click="run('select',word.id)"><strong lang="en">{{word.word}}</strong><span>{{word.zh}}</span></Button></nav></aside>
    <section class="lesson"><header class="word-heading"><div><p class="eyebrow">{{m.group==='space'?'01 / SPATIAL RELATIONSHIPS':'02 / WALK & RUN'}}</p><h2>{{m.kind==='quiz'?'观察这段动画':m.word.word}}</h2><p id="meaning" v-if="m.kind==='visual'">{{m.word.zh}}</p></div><Button v-if="m.kind==='visual'" aria-label="朗读当前英文词汇" @click="run('speak')">听发音</Button></header>
     <div class="scene-card"><div class="scene-meta"><span>{{m.group==='space'?'空间关系':'行走与奔跑'}} · 动态观察</span><span>{{m.playStatus}}</span></div><div id="scene" class="scene" :class="{comparing:m.compare&&m.group==='motion'&&m.kind==='visual'}" v-html="m.svg"/></div>
     <template v-if="m.kind==='visual'"><div v-if="m.group==='motion'" class="motion-tools"><label><Switch :model-value="m.compare" size="19" @update:model-value="run('compare',$event)"/>同步对照</label><Button @click="picker=true">参考动作：{{m.entries.find(w=>w.id===m.reference)?.word}}</Button><p>看这里：{{m.cue}}。地面标线显示前进速度。</p></div><div class="explanations"><section class="sentence"><p class="eyebrow">PUT IT IN A SENTENCE</p><p id="sentence" lang="en">{{m.word.sentence}}</p><p id="translation">{{m.word.translation}}</p></section><section class="notice"><h3>留意这个区别</h3><p>{{m.word.hint}}</p></section></div><nav class="word-navigation"><Button @click="run('move',-1)">← 上一个</Button><span>{{m.position}} / {{m.entries.length}}</span><Button @click="run('move',1)">下一个 →</Button></nav><Button tag="a" :href="m.quizHref" class="quiz-link"><span><strong>看动作，选表达</strong><small>准备好后，测测自己记住了多少。</small></span><b>去测试 →</b></Button></template>
     <template v-else><div class="answers"><Button v-for="word in m.options" :key="word.id" :disabled="m.answered" :class="{correct:m.answered&&word.id===m.word.id,wrong:m.answered&&word.id===m.chosen&&word.id!==m.word.id}" @click="run('answer',word.id)">{{word.word}}</Button></div><p role="status">{{m.feedback}}</p><Button @click="run('next')">换一题</Button></template>
    </section>
   </div>
   <footer>先看动作，再说单词，最后放进自己的句子里。<p><Button v-if="m.kind==='visual'" tag="a" class="atlas-link" href="english-visual-atlas.svg" download="英语动画词汇图谱.svg">下载词汇图谱 ↓</Button><Button v-else tag="a" :href="m.backHref">返回学习</Button></p><Collapse v-model="opened"><CollapseItem title="关于素材" name="credits">角色参考 Ian Xiaohei Illustrations · <a href="english-motion-NOTICE.txt" target="_blank" rel="noopener">来源与 MIT 授权</a></CollapseItem></Collapse></footer>
  </div>
  <Popup :show="m.help" round closeable close-icon="cross" :style="{width:'min(90vw,520px)',padding:'30px'}" @update:show="run('help',$event)"><h2>看动作，记单词</h2><p>17 个空间关系表达、16 种行走与奔跑表达，点选词汇后动画会自动循环播放。</p><p>手机也能左右对照动作，观察步幅、脚尖和身体姿态的差别，再读例句。点击“看动作，选表达”进入测试页。</p></Popup>
  <Popup v-model:show="picker" position="bottom" round><Picker :columns="columns" :model-value="[m.reference]" @confirm="run('reference',$event.selectedValues[0]);picker=false" @cancel="picker=false"><template #cancel><span aria-label="关闭" class="cross">×</span></template></Picker></Popup>
 </template>
 <template v-else>
  <header class="sentence-topbar"><span class="brand"><img :src="'brand-logo.webp'" alt="" width="32" height="32">逆流</span><span>Unit {{m.practice.unit?.number}} · {{m.practice.unit?.title}}</span><Button tag="a" :href="unitHref">返回 Unit {{m.practice.unit?.number}}</Button></header><div class="sentence-shell"><nav><Button v-if="m.practice.topic" tag="a" :href="unitHref" aria-label="返回知识点" icon="arrow-left">返回知识点</Button><Button tag="a" :href="m.practice.backHref||'units.html?subject=english&term=upper'">{{m.practice.unit?'返回课堂':'英语目录'}}</Button></nav>
  <section v-if="m.practice.error"><h1>暂时无法开始练习</h1><p>{{m.practice.error}}</p><Button v-if="m.practice.unit" tag="a" :href="unitHref">重新选择知识点</Button></section>
  <section v-else-if="!m.practice.topic"><header><p>八年级上册 · 句子闯关</p><h1>Unit {{m.practice.unit.number}} · {{m.practice.unit.title}}</h1><p>句子互动已完成 {{m.unitProgress.completed}}/{{m.unitProgress.total}} 项</p></header><CellGroup><Cell v-for="topic in m.topicProgress" :key="topic.id" tag="a" :href="unitHref+'&topic='+encodeURIComponent(topic.id)" :title="topic.title" :value="topic.completed+'/'+topic.total+(topic.completed===topic.total?' ✓':'')" is-link/></CellGroup></section>
  <template v-else>
   <header><p>Unit {{m.practice.unit.number}} · {{m.practice.topic.title}}</p><div class="score"><span>{{m.results?'本轮练习完成':`用键盘输入英文，按空格确认（${(m.phase==='sentence'?m.words.length:m.wordIndex)+1}/${m.words.length+1}）`}}</span><strong aria-label="本轮练习积分">{{m.score}}</strong></div><Progress :percentage="m.results?100:(m.phase==='sentence'?m.words.length:m.wordIndex)/(m.words.length+1)*100" :show-pivot="false"/></header>
   <section v-if="m.results"><h1>本轮练习完成</h1><p>独立完成 {{m.summary.independent}} / {{m.summary.total}}　最高连击 {{m.bestCombo}}　练习积分 {{m.score}}</p><div class="actions"><Button type="primary" @click="run('restart',m.round.results.some(r=>r.points<100))">{{m.round.results.some(r=>r.points<100)?'重练需巩固的句子':'再来一轮'}}</Button><Button v-if="m.round.results.some(r=>r.points<100)" @click="run('restart',false)">全部重练</Button><Button tag="a" :href="unitHref">切换知识点</Button></div><div v-for="(result,i) in m.round.results" :key="result.id" class="result"><h2>{{m.round.sentences[i].title}}</h2><p lang="en">{{m.round.sentences[i].en}}</p><p>{{m.round.sentences[i].zh}}</p><p>{{result.revealed?'看过答案':result.wrong?'订正后完成':'独立完成'}}</p><p>{{m.round.sentences[i].explanation}}</p></div></section>
   <section v-else class="typing-task" :data-phase="m.phase">
    <Button v-if="m.phase==='preview'" type="primary" block @click="start">按任意键，开始造这个句子</Button>
    <div v-if="m.phase==='preview'||m.done" class="grammar"><div v-for="(group,i) in m.groups" :key="i" class="grammar-group"><small>{{group.role}}</small><div class="grammar-words"><div v-for="(word,j) in group.words" :key="j" class="grammar-word"><small>/{{word.ipa}}/</small><strong lang="en">{{word.en}}</strong><span>{{word.gloss}}</span><small>{{word.pos}}</small></div></div></div></div>
    <h1>{{m.phase==='word'?m.words[m.wordIndex].gloss:m.current.zh}}</h1><p v-if="m.phase==='word'&&m.round.index===0&&m.wordIndex===0&&!m.done">在键盘上输入 <strong lang="en">{{m.expected}}</strong></p>
    <Field v-if="m.phase!=='preview'" ref="input" :model-value="m.draft" :label="m.phase==='sentence'?'输入完整的英文句子':'输入对应的英文单词'" type="textarea" rows="2" maxlength="300" :readonly="m.done&&!touchTyping" :error="m.typing==='wrong'" autocomplete="off" autocapitalize="off" autocorrect="off" :spellcheck="false" enterkeyhint="done" @update:model-value="update" @keydown="key" @beforeinput="beforeInput" @compositionstart="composing=true" @compositionend="composing=false;update($event.target.value)"/>
    <p v-if="m.answerOpen&&!m.done" lang="en">{{m.expected}}</p><p role="status">{{m.message}}</p><div v-if="m.phase!=='preview'" class="actions"><Button @click="run('speak')">播放发音</Button><template v-if="m.done"><Button type="primary" @click="next">下一题</Button><Button @click="run('redo');focus()">重答</Button></template><template v-else><Button type="primary" @click="run('submit')">提交</Button><Button :aria-expanded="m.answerOpen" @click="run('reveal');focus()">{{m.answerOpen?'隐藏答案':'显示答案'}}</Button></template></div>
   </section>
   <Collapse v-model="opened"><CollapseItem title="关于本次练习" name="rules"><p>每个单词及整句各算一题。首答正确得1000分，错误后订正得300分，看过答案的题不计分；重答不重复加分。首答正确增加连击，错误或看答案中断连击。每句开始时重置句内进度，积分累计到本轮结束。</p><p>本题组为 Unit {{m.practice.unit.number}}「{{m.practice.topic.title}}」的原创练习；刷新重开，积分不写入课程成绩或奖励。</p></CollapseItem></Collapse>
  </template>
 </div></template>
</main>
</template>
<style scoped>
.english-labs{--van-primary-color:#22634b;--van-button-primary-background:#22634b;--van-button-primary-border-color:#22634b;--van-tabs-bottom-bar-color:#22634b;--van-switch-on-background:#22634b;--van-progress-color:#22634b;max-width:1100px;margin:auto;padding:20px clamp(14px,4vw,36px) 60px;color:#24352e;font:16px/1.7 system-ui,-apple-system,"Microsoft YaHei",sans-serif}.english-labs,.english-labs :deep(*){box-sizing:border-box}.english-labs nav,.actions,.score{display:flex;gap:12px;align-items:center;flex-wrap:wrap;justify-content:space-between}.english-labs :deep(.van-button){min-height:44px;height:auto;padding:10px 14px;white-space:normal;font:inherit;text-decoration:none}.english-labs header{margin:28px 0}.english-labs h1{font-size:clamp(25px,4vw,38px);line-height:1.4;overflow-wrap:anywhere}.english-labs h2{font-size:24px;margin:0;overflow-wrap:anywhere}.english-labs p{overflow-wrap:anywhere}.visual-layout{display:grid;grid-template-columns:230px minmax(0,1fr);gap:24px;margin-top:24px}.visual-layout.is-quiz{display:block;max-width:780px;margin:24px auto}.word-list{display:flex;flex-direction:column;gap:8px;max-height:650px;overflow:auto}.word-list :deep(.van-button__text){display:flex;gap:10px;align-items:center;justify-content:space-between;width:100%}.word-list span{font-size:13px}.lesson{min-width:0;background:#fff;border:1px solid #e0e7e0;border-radius:14px;padding:clamp(14px,3vw,26px)}.word-heading{display:flex;justify-content:space-between;align-items:start;gap:12px}.scene{width:100%;overflow:hidden}.scene :deep(svg){display:block;width:100%;height:auto}.scene.comparing :deep(svg){min-height:180px}.comparison label{display:flex;align-items:center;gap:16px}.comparison .van-button{margin-top:12px}.examples{border-top:1px solid #e0e7e0;margin-top:24px;padding-top:12px}.lesson nav{margin:24px 0}.answers{display:grid;gap:12px;margin:20px 0}.english-labs footer{margin-top:28px}.english-labs :deep(.van-popup__close-icon){min-width:44px;min-height:44px;display:grid;place-items:center;top:4px;right:4px}.cross{display:grid;place-items:center;min-height:44px;min-width:44px;font-size:26px}.score strong{font-size:28px;color:#22634b}.typing-task{padding:26px 0}.grammar{display:flex;flex-wrap:wrap;gap:16px;margin:24px 0}.grammar-group{max-width:100%;padding:8px 12px;border-top:3px solid #729b83;background:#f2f6f2;border-radius:4px}.grammar-words{display:flex;flex-wrap:wrap;gap:14px}.grammar-word{display:flex;flex-direction:column;align-items:center;max-width:100%;overflow-wrap:anywhere}.grammar-word strong{font-size:22px}.grammar-word small{font-size:12px;color:#687a6d}.typing-task :deep(.van-field){flex-direction:column;padding:14px;border:1px solid #bdcdbf;border-radius:10px}.typing-task :deep(.van-field__label){width:100%;margin:0 0 8px}.typing-task :deep(textarea){font-size:22px}.actions{justify-content:flex-start;margin:22px 0}.result{padding:22px 0;border-bottom:1px solid #dae3dc}.english-labs a:focus-visible{outline:3px solid #22634b;outline-offset:3px}@media(max-width:640px){.visual-layout{grid-template-columns:minmax(0,1fr)}.word-list{flex-direction:row;max-height:none;overflow:auto;padding-bottom:10px}.word-list :deep(.van-button){flex:0 0 auto}.word-list :deep(.van-button__text){flex-direction:column;gap:0}.word-heading h2{font-size:28px}.english-labs nav{gap:8px}.grammar-word strong{font-size:19px}.grammar-words{gap:9px}.grammar-group{padding:6px 8px}}

